    let shape = b.append_shape(b.root_id(), parsed(&d), &mut Run).unwrap();
    finish(&mut b, &d);
    b.rollback_request(&draft, request).unwrap();
    assert!(b.scene(b.root_id()).unwrap().shape(shape).is_none());
